-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the rockphysics capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- rockphysics / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'rockphysics' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e42593a8a34f79fea1b55bf17308b7d2' and fields = '[{"key": "brine_rho", "tol": 0.5, "unit": "kg/m3", "label": "Brine density", "expected": 1017.8249875}, {"key": "brine_k_gpa", "tol": 0.005, "unit": "GPa", "label": "Brine bulk modulus", "expected": 2.6978112899395996}, {"key": "gas_k_mpa", "tol": 0.1, "unit": "MPa", "label": "Gas bulk modulus", "expected": 55.71865290286663}, {"key": "oil_rho", "tol": 0.5, "unit": "kg/m3", "label": "Live-oil density", "expected": 777.0630099023522}, {"key": "vrh_k_gpa", "tol": 0.05, "unit": "GPa", "label": "Frame K, VRH 70/30 quartz/clay", "expected": 30.87940062475596}, {"key": "wood_k_mpa", "tol": 0.5, "unit": "MPa", "label": "Wood mixed-fluid K at Sw 0.8", "expected": 257.3340919366766}]'::jsonb then 'old'
              when md5(prompt) = 'd638351b30507cdaee8d80ba6d99cdc6' and fields = '[{"key": "brine_rho", "tol": 0.5, "unit": "kg/m3", "label": "Brine density", "expected": 1017.8249875}, {"key": "brine_k_gpa", "tol": 0.005, "unit": "GPa", "label": "Brine bulk modulus", "expected": 2.6978112899395996}, {"key": "gas_k_mpa", "tol": 0.1, "unit": "MPa", "label": "Gas bulk modulus", "expected": 55.71865290286663}, {"key": "oil_rho", "tol": 0.5, "unit": "kg/m3", "label": "Live-oil density", "expected": 777.0630099023522}, {"key": "vrh_k_gpa", "tol": 0.05, "unit": "GPa", "label": "Frame K, VRH 70/30 quartz/clay", "expected": 30.87940062475596}, {"key": "wood_k_mpa", "tol": 0.5, "unit": "MPa", "label": "Wood mixed-fluid K at Sw 0.8", "expected": 257.3340919366766}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'rockphysics' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book rockphysics refused: rockphysics/beginner matches neither its published form (prompt md5 e42593a8a34f79fea1b55bf17308b7d2) nor its W1 form (prompt md5 d638351b30507cdaee8d80ba6d99cdc6), with the fields this file was generated against';
  end if;

  -- rockphysics / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'rockphysics' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '929030505f7c94701b712cec9de58439' and fields = '[{"key": "mu_gpa", "tol": 0.01, "unit": "GPa", "label": "Shear modulus (fluid-blind)", "expected": 7.29}, {"key": "ksat_insitu", "tol": 0.01, "unit": "GPa", "label": "In-situ saturated K", "expected": 13.32}, {"key": "kdry_gpa", "tol": 0.01, "unit": "GPa", "label": "Dry-frame K (inverse Gassmann)", "expected": 7.350343061720982}, {"key": "gas_vp", "tol": 1, "unit": "m/s", "label": "Gas-case vp", "expected": 2905.6972280296195}, {"key": "gas_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gas-case density", "expected": 2038.7104517793223}, {"key": "gc_vs", "tol": 1, "unit": "m/s", "label": "Greenberg-Castagna vs at vp 3000", "expected": 1521.197276567149}]'::jsonb then 'old'
              when md5(prompt) = '3608d6b89745865f6a60a0314c898dee' and fields = '[{"key": "mu_gpa", "tol": 0.01, "unit": "GPa", "label": "Shear modulus (fluid-blind)", "expected": 7.29}, {"key": "ksat_insitu", "tol": 0.01, "unit": "GPa", "label": "In-situ saturated K", "expected": 13.32}, {"key": "kdry_gpa", "tol": 0.01, "unit": "GPa", "label": "Dry-frame K (inverse Gassmann)", "expected": 7.350343061720982}, {"key": "gas_vp", "tol": 1, "unit": "m/s", "label": "Gas-case vp", "expected": 2905.6972280296195}, {"key": "gas_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gas-case density", "expected": 2038.7104517793223}, {"key": "gc_vs", "tol": 1, "unit": "m/s", "label": "Greenberg-Castagna vs at vp 3000", "expected": 1521.197276567149}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'rockphysics' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book rockphysics refused: rockphysics/intermediate matches neither its published form (prompt md5 929030505f7c94701b712cec9de58439) nor its W1 form (prompt md5 3608d6b89745865f6a60a0314c898dee), with the fields this file was generated against';
  end if;

  -- rockphysics / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '29275780598190d11bc93de24adcd976' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb then 'old'
              when md5(prompt) = '37f9c72d59288939d322371f9971e284' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book rockphysics refused: rockphysics/advanced matches neither its published form (prompt md5 29275780598190d11bc93de24adcd976) nor its W1 form (prompt md5 37f9c72d59288939d322371f9971e284), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book rockphysics: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book rockphysics refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. The Ekene SAND sits at 60 degC and 25 MPa with 35,000 ppm brine, 0.6-gravity gas and a 35 API oil at GOR 50 L/L. Compute each fluid with the engine, mix the 70/30 quartz/clay frame with Voigt-Reuss-Hill, and mix the pore fluid at Sw 0.8 with Wood''s equation. Report what the panel shows.',
           fields = '[{"key": "brine_rho", "tol": 0.5, "unit": "kg/m3", "label": "Brine density", "expected": 1017.8249875}, {"key": "brine_k_gpa", "tol": 0.005, "unit": "GPa", "label": "Brine bulk modulus", "expected": 2.6978112899395996}, {"key": "gas_k_mpa", "tol": 0.1, "unit": "MPa", "label": "Gas bulk modulus", "expected": 55.71865290286663}, {"key": "oil_rho", "tol": 0.5, "unit": "kg/m3", "label": "Live-oil density", "expected": 777.0630099023522}, {"key": "vrh_k_gpa", "tol": 0.05, "unit": "GPa", "label": "Frame K, VRH 70/30 quartz/clay", "expected": 30.87940062475596}, {"key": "wood_k_mpa", "tol": 0.5, "unit": "MPa", "label": "Wood mixed-fluid K at Sw 0.8", "expected": 257.3340919366766}]'::jsonb
     where app_slug = 'rockphysics' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd638351b30507cdaee8d80ba6d99cdc6' and fields = '[{"key": "brine_rho", "tol": 0.5, "unit": "kg/m3", "label": "Brine density", "expected": 1017.8249875}, {"key": "brine_k_gpa", "tol": 0.005, "unit": "GPa", "label": "Brine bulk modulus", "expected": 2.6978112899395996}, {"key": "gas_k_mpa", "tol": 0.1, "unit": "MPa", "label": "Gas bulk modulus", "expected": 55.71865290286663}, {"key": "oil_rho", "tol": 0.5, "unit": "kg/m3", "label": "Live-oil density", "expected": 777.0630099023522}, {"key": "vrh_k_gpa", "tol": 0.05, "unit": "GPa", "label": "Frame K, VRH 70/30 quartz/clay", "expected": 30.87940062475596}, {"key": "wood_k_mpa", "tol": 0.5, "unit": "MPa", "label": "Wood mixed-fluid K at Sw 0.8", "expected": 257.3340919366766}]'::jsonb) from public.academy_capstones where app_slug = 'rockphysics' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book rockphysics refused: rockphysics/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. The logged sand (vp 3200 m/s, vs 1800 m/s, rho 2250 kg/m3; porosity 0.25, K_min 37 GPa) is brine-saturated. Recover the dry frame with inverse Gassmann, substitute to gas, and report the panel. Where the sonic has no shear, predict vs at vp 3000 m/s with Greenberg-Castagna for the 70/30 sand/shale mix.',
           fields = '[{"key": "mu_gpa", "tol": 0.01, "unit": "GPa", "label": "Shear modulus (fluid-blind)", "expected": 7.29}, {"key": "ksat_insitu", "tol": 0.01, "unit": "GPa", "label": "In-situ saturated K", "expected": 13.32}, {"key": "kdry_gpa", "tol": 0.01, "unit": "GPa", "label": "Dry-frame K (inverse Gassmann)", "expected": 7.350343061720982}, {"key": "gas_vp", "tol": 1, "unit": "m/s", "label": "Gas-case vp", "expected": 2905.6972280296195}, {"key": "gas_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gas-case density", "expected": 2038.7104517793223}, {"key": "gc_vs", "tol": 1, "unit": "m/s", "label": "Greenberg-Castagna vs at vp 3000", "expected": 1521.197276567149}]'::jsonb
     where app_slug = 'rockphysics' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3608d6b89745865f6a60a0314c898dee' and fields = '[{"key": "mu_gpa", "tol": 0.01, "unit": "GPa", "label": "Shear modulus (fluid-blind)", "expected": 7.29}, {"key": "ksat_insitu", "tol": 0.01, "unit": "GPa", "label": "In-situ saturated K", "expected": 13.32}, {"key": "kdry_gpa", "tol": 0.01, "unit": "GPa", "label": "Dry-frame K (inverse Gassmann)", "expected": 7.350343061720982}, {"key": "gas_vp", "tol": 1, "unit": "m/s", "label": "Gas-case vp", "expected": 2905.6972280296195}, {"key": "gas_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gas-case density", "expected": 2038.7104517793223}, {"key": "gc_vs", "tol": 1, "unit": "m/s", "label": "Greenberg-Castagna vs at vp 3000", "expected": 1521.197276567149}]'::jsonb) from public.academy_capstones where app_slug = 'rockphysics' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book rockphysics refused: rockphysics/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Put the Ekene shale (vp 2743, vs 1394, rho 2450) over the SAND and screen both cases: the logged brine sand and its gas-substituted twin from the Professional tier. Report Shuey intercept and gradient for each, the largest absolute gap between Shuey and exact Zoeppritz on the brine case over 0 to 40 degrees, the exact Zoeppritz Rpp at 30 degrees for the gas case, and the wedge tuning thickness at 25 Hz.',
           fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb
     where app_slug = 'rockphysics' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book rockphysics refused: rockphysics/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '37f9c72d59288939d322371f9971e284' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb) from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book rockphysics refused: rockphysics/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book rockphysics: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
